"use client";
import { useLayoutEffect, useRef, useState, type CSSProperties } from "react";
import "./continuous-tabs.css";
export interface ContinuousTab {
  id: string;
  label: React.ReactNode;
}
/** A controlled selection group. Labels never move; one retained marker follows selection. */
export function ContinuousTabs({
  items,
  value,
  onValueChange,
  label = "View",
  color,
  duration,
  className = "",
  style,
}: {
  className?: string;
  style?: CSSProperties;
  items: ContinuousTab[];
  value: string;
  onValueChange: (id: string) => void;
  label?: string;
  color?: string;
  duration?: number;
}) {
  const root = useRef<HTMLDivElement>(null),
    [pose, setPose] = useState({ x: 0, width: 0 });
  useLayoutEffect(() => {
    const measure = () => {
      const button =
        root.current?.querySelector<HTMLElement>(`[data-active="true"]`);
      if (button) setPose({ x: button.offsetLeft, width: button.offsetWidth });
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (root.current) observer.observe(root.current);
    return () => observer.disconnect();
  }, [value, items]);
  return (
    <div
      className={`roc-tabs ${className}`}
      ref={root}
      style={
        {
          "--roc-marker": color,
          "--roc-duration": duration ? `${duration}ms` : undefined,
          ...style,
        } as CSSProperties
      }
      role="group"
      aria-label={label}
    >
      <span
        aria-hidden="true"
        className="roc-tab-marker"
        style={{ transform: `translateX(${pose.x}px)`, width: pose.width }}
      />
      {items.map((item) => (
        <button
          type="button"
          key={item.id}
          data-active={value === item.id}
          aria-pressed={value === item.id}
          onClick={() => onValueChange(item.id)}
        >
          {item.label}
        </button>
      ))}
    </div>
  );
}

@import "./surface.css";
.roc-tabs * {
  box-sizing: border-box;
}
.roc-tabs button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-tabs button:focus-visible {
  outline: 2px solid var(--roc-accent, #64735f);
  outline-offset: 5px;
}
.roc-tabs {
  position: relative;
  display: inline-flex;
  border: 1px solid var(--roc-line, #d8dcd4);
  padding: 4px;
  border-radius: 9px;
  background: #f0f1eb;
  max-width: 100%;
}
.roc-tabs button {
  position: relative;
  z-index: 1;
  background: none;
  border: 0;
  padding: 11px 18px;
  font-size: 12px;
  border-radius: 5px;
  white-space: nowrap;
}
.roc-tabs button[data-active="true"] {
  color: #2c4227;
}
.roc-tab-marker {
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  border-radius: 5px;
  background: #fff;
  box-shadow: 0 1px 4px #20282012;
  transition:
    transform 0.36s cubic-bezier(0.22, 0.8, 0.25, 1),
    width 0.36s cubic-bezier(0.22, 0.8, 0.25, 1);
}
@media (max-width: 480px) {
  .roc-tabs button {
    padding: 10px 12px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-tabs * {
    transition: none !important;
    animation: none !important;
  }
}
.roc-tab-marker {
  transition:
    transform var(--roc-duration, 360ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    width var(--roc-duration, 360ms) cubic-bezier(0.22, 0.8, 0.25, 1);
  background: var(--roc-marker, #fff);
}
@media (prefers-reduced-motion: reduce) {
  .roc-tab-marker {
    transition: none !important;
  }
}

/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: 2px solid var(--roc-accent, #64735f);
  outline-offset: 3px;
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}
